import math

def source_tf_component(tf_array, l_d, l_avg, k1, b, delta):
    num = (k1 + 1) * tf_array
    den = k1 * (1 - b + b * l_d / l_avg) + tf_array
    return num / den + delta

def source_idf_component(df, N):
    return math.log((N + 1) / df)

